            let wc_len = emu.regs().r9 as i32;
            let mb_str = emu.maps.read_qword(emu.regs().rsp + 0x28).unwrap_or(0);
            let mb_len = emu.maps.read_qword(emu.regs().rsp + 0x30).unwrap_or(0) as i32;
